const preferenceKey: string | null = "btpb:language";
const localeCache = 'btpb-language-preference-v1';
let synced: string | null = null;
export function btpbLanguage(): 'en' | 'it' {
  if (typeof window === 'undefined') return 'en';
  try {
    if (preferenceKey) {
      const value = window.localStorage.getItem(preferenceKey);
      if (value === 'it' || value === '\"it\"') return 'it';
      if (value === 'en' || value === '\"en\"') return 'en';
    }
    if (document.documentElement.lang.toLowerCase().startsWith("it")) return "it";
  } catch { /* unavailable storage: use the default */ }
  return 'en';
}
export function btpbText(value: string): string;
export function btpbText(value: string | null | undefined): string | null | undefined;
export function btpbText(value: string | null | undefined): string | null | undefined {
  if (!value || btpbLanguage() === 'it') return value;
  const trimmed = value.trim().replace(/\s+/g,' ');
  let translation = Object.prototype.hasOwnProperty.call(english,trimmed) ? english[trimmed] : undefined;
  if (!translation) {
    const patterns: [RegExp,string][] = [
      [/^Ogni girone deve contenere almeno (.+) squadre, perché hai scelto (.+) qualificate per girone\.$/, 'Each group must have at least $1 teams because you selected $2 qualifiers per group.'],
      [/^Lo spostamento lascerebbe un girone con meno di (.+) squadre\.$/, 'Moving the team would leave a group with fewer than $1 teams.'],
      [/^Timer non valido per (.+)\.$/, 'Invalid timer for $1.'],
      [/^Target goal non valido per (.+)\.$/, 'Invalid goal target for $1.'],
      [/^Impossibile ricostruire l'ordine della squadra (.+)\.$/, 'Unable to reconstruct the order for team $1.'],
      [/^Con questa distribuzione ogni girone deve avere almeno (.+) squadre\.$/, 'With this distribution, each group needs at least $1 teams.'],
    ];
    for (const [pattern,replacement] of patterns) if(pattern.test(trimmed)){translation=trimmed.replace(pattern,replacement);break;}
  }
  if (translation === undefined) return value;
  return (value.match(/^\s*/)?.[0] ?? '') + translation + (value.match(/\s*$/)?.[0] ?? '');
}
export function btpbError(value: string): string;
export function btpbError(value: string | null | undefined): string | null | undefined;
export function btpbError(value: string | null | undefined): string | null | undefined {
  if (!value) return value;
  if (btpbLanguage() === 'en') return btpbText(value);
  const source = value.trim();
  for (const [italian, translated] of Object.entries(english)) if (translated === source) return italian;
  const status = /^Match cannot be started from status (.+)$/.exec(source);
  if(status) return 'La partita non può essere avviata dallo stato '+status[1];
  return value;
}
export function btpbStateLabel(value: string): string {
  const states: Record<string,[string,string]> = {draft:['Draft','Bozza'],active:['Active','Attivo'],completed:['Completed','Concluso'],groups:['Group stage','Gironi'],knockout:['Knockout stage','Eliminazione diretta'],finished:['Finished','Concluso']};
  return states[value]?.[btpbLanguage() === 'it' ? 1 : 0] ?? value;
}
const listeners = new Set<() => void>();
let interval: number | undefined;
let observer: MutationObserver | undefined;
let last = 'en';
function notify() { const next = btpbLanguage(); if(next !== last){last=next;listeners.forEach(listener=>listener());} }
function subscribe(listener: () => void) {
  listeners.add(listener);
  if(listeners.size===1){
    last=btpbLanguage();
    window.addEventListener('storage',notify);
    // Storage events do not fire in the tab that wrote the preference.
    observer=new MutationObserver(notify);
    observer.observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
    interval=window.setInterval(notify,150);
  }
  return ()=>{listeners.delete(listener);if(!listeners.size){window.removeEventListener('storage',notify);observer?.disconnect();if(interval!==undefined)window.clearInterval(interval);}};
}
function syncPushLanguage(language: string){
  if (typeof caches === 'undefined' || synced === language) return;
  synced=language;
  void caches.open(localeCache).then(cache=>cache.put(new URL('/__btpb_language__',window.location.origin).href,new Response(language))).catch(()=>{synced=null;});
}
export function useBtpbUiLanguage() {
  const language = useSyncExternalStore(subscribe,btpbLanguage,()=> 'en' as const);
  useEffect(()=>{syncPushLanguage(language);},[language]);
  return language;
}
